#!/usr/bin/env bash
# Mutation proof for bunta-ops mail-read attachments (generated by agents-bunta-ops.org): each sabotaged copy of the tool MUST fail test-bunta-ops.py by a NAMED failure.
set -uo pipefail
HERE="$(CDPATH= cd -- "$(dirname -- "$0")" && pwd -P)"
TOOL="$HERE/../../../bin/bunta-ops"
TMP="$(mktemp -d)"; trap 'rm -rf "$TMP"' EXIT
fail=0; killed=0
mutate() {
  local name="$1" expr="$2" d="$TMP/$1"
  mkdir -p "$d/bin" "$d/share/dotcortex/tests"; cp "$TOOL" "$d/bin/bunta-ops"; sed -i "$expr" "$d/bin/bunta-ops"
  cp "$HERE/test-bunta-ops.py" "$d/share/dotcortex/tests/"
  if cmp -s "$TOOL" "$d/bin/bunta-ops"; then echo "MUTATION NOT APPLIED: $name"; fail=1; return; fi
  mkdir -p "$d/x/y/z"; ln -s "$d/bin" "$d/x/bin" 2>/dev/null
  out="$(python3 - "$d" <<'PY' 2>&1
import sys, unittest, importlib.util, pathlib
d = pathlib.Path(sys.argv[1]); src = (d / 'share/dotcortex/tests/test-bunta-ops.py').read_text().replace("Path(__file__).resolve().parents[3] / 'bin/bunta-ops'", "Path(%r)" % str(d / 'bin/bunta-ops'))
ns = {'__name__': 't', '__file__': str(d / 'share/dotcortex/tests/t.py')}; exec(compile(src.split("if __name__")[0], 't', 'exec'), ns)
suite = unittest.defaultTestLoader.loadTestsFromTestCase(ns['AttachmentTests']); suite.addTests(unittest.defaultTestLoader.loadTestsFromTestCase(ns['BuntaOpsTests']))
r = unittest.TextTestRunner(stream=open('/dev/null', 'w')).run(suite)
print('FAILED' if (r.failures or r.errors) else 'OK'); [print('FAIL:', str(t[0]).split()[0]) for t in r.failures + r.errors]
PY
)"
  names="$(printf '%s\n' "$out" | grep '^FAIL:' | head -3 | sed 's/FAIL: //' | tr '\n' ' ')"
  if [ -n "$names" ]; then killed=$((killed+1)); echo "killed: $name by: $names"; else echo "SURVIVED: $name"; fail=1; fi
}
mutate no-name-sanitising      "s/    name = ATTACHMENT_NAME.sub('_', raw).lstrip('.')\[:80\]/    name = raw/"
mutate size-cap-removed        "s/        if len(data) > MAX_ATTACHMENT:/        if False:/"
mutate file-mode-world         "s/os.fchmod(descriptor, 0o600)/os.fchmod(descriptor, 0o644)/"
mutate index-off-by-one        "s/        part = parts\[number - 1\]/        part = parts[number]/"
mutate missing-part-not-refused "s/        if number > len(parts):/        if False:/"
mutate link-target-allowed     "s/        if target.is_symlink() or target.is_dir():/        if False:/"
mutate message-link-followed   "s/                 and not (MAILDIR \/ state \/ file_id).is_symlink()), None)/                 ), None)/"
mutate default-read-broken     "s/    if len(args) == 1:/    if len(args) == 99:/"
mutate runs-mailcortex         "s/        parts = message_attachments(args\[0\])\n        if not parts:/&/;s/            print('(no attachments)')/            run(['mailcortex', 'read', SEAT_INBOX, args[0]]); print('(no attachments)')/"
mutate any-index-shape         "s/re.fullmatch(r'\[1-9\]\[0-9\]?', args\[2\])/args[2].lstrip('-').isdigit()/"
mutate listing-size-wrong      "s/            size = len(part.get_payload(decode=True) or b'')/            size = 0/"
mutate saves-outside-in        "s|        folder = SCRATCH / 'in'|        folder = SCRATCH|"
mutate shape-refusal-dropped   "s/    raise Refused('mail-read <file-id> \[attachments | attachment <n>\]')\$/    return 0/"
echo "mutants: $killed killed"
[ "$fail" = 0 ] || exit 1
